program_text='''def transform(grid):
    h, w = len(grid), len(grid[0])
    ref = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    if not ref:
        return [row[:] for row in grid]
    r0, c0 = min(r for r, c in ref), min(c for r, c in ref)
    pattern = {(r-r0, c-c0) for r, c in ref}
    out = [row[:] for row in grid]
    for color in range(10):
        if color in (1, 4):
            continue
        remaining = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        # A color can mark more than one copy of the reference shape. Repeatedly
        # choose the translated pattern that explains the most remaining marks.
        while remaining:
            best_origin, best_hits = None, set()
            for dr in range(h):
                for dc in range(w):
                    if not all(0 <= dr+pr < h and 0 <= dc+pc < w for pr, pc in pattern):
                        continue
                    hits = {(r, c) for r, c in remaining if (r-dr, c-dc) in pattern}
                    if len(hits) > len(best_hits):
                        best_origin, best_hits = (dr, dc), hits
            if best_origin is None or not best_hits:
                break
            dr, dc = best_origin
            for pr, pc in pattern:
                out[dr+pr][dc+pc] = color
            remaining -= best_hits
    return out
'''
